// Some portions generated by Claude
import assert from "node:assert/strict";
import test, { afterEach } from "node:test";
import {
  compactTerm,
  edgeTooltip,
  nodeTooltip,
  setNamespaces,
  termCode,
  termTooltip,
} from "../../../main/frontend/graph-explorer/graph-terms.ts";
import {
  namespacesEndpoint,
  parseNamespaceRows,
} from "../../../main/frontend/graph-explorer/transport.ts";

afterEach(() => setNamespaces([]));

test("a repository namespace shortens an IRI, and it replaces the cache of earlier answers", () => {
  const iri = "http://rdf4j.org/schema/rdf4j#nativeStore";
  assert.equal(compactTerm(iri), "nativeStore");
  setNamespaces([{ prefix: "rdf4j", name: "http://rdf4j.org/schema/rdf4j#" }]);
  assert.equal(compactTerm(iri), "rdf4j:nativeStore");
  assert.equal(termCode({ id: iri, kind: "iri" }), "rdf4j:nativeStore");
  setNamespaces([{ prefix: "x", name: "http://rdf4j.org/schema/rdf4j#" }]);
  assert.equal(compactTerm(iri), "x:nativeStore");
  setNamespaces([]);
  assert.equal(compactTerm(iri), "nativeStore");
});

test("the longest matching repository namespace wins, and repository namespaces beat the built-in ones", () => {
  setNamespaces([
    { prefix: "ex", name: "http://example.org/" },
    { prefix: "exv", name: "http://example.org/vocab/" },
    { prefix: "sdo", name: "http://schema.org/" },
  ]);
  assert.equal(compactTerm("http://example.org/vocab/Thing"), "exv:Thing");
  assert.equal(compactTerm("http://example.org/other"), "ex:other");
  assert.equal(compactTerm("http://schema.org/name"), "sdo:name");
  // Built-in prefixes still apply to namespaces the repository does not declare.
  assert.equal(compactTerm("http://www.w3.org/2000/01/rdf-schema#label"), "rdfs:label");
});

test("a repository-declared built-in prefix is not reused for its built-in namespace", () => {
  setNamespaces([
    { prefix: "ex", name: "urn:custom#" },
    { prefix: "rdf", name: "urn:custom#" },
  ]);
  assert.equal(compactTerm("urn:custom#type"), "ex:type");
  assert.equal(compactTerm("http://www.w3.org/1999/02/22-rdf-syntax-ns#type"), "type");
});

test("an empty prefix renders as :local; entries without a namespace IRI are ignored", () => {
  setNamespaces([
    { prefix: "", name: "http://example.org/" },
    { prefix: "bad", name: "" },
    { prefix: "none" },
  ]);
  assert.equal(compactTerm("http://example.org/alice"), ":alice");
  assert.equal(compactTerm("http://other.org/bad"), "bad");
});

test("compacting an IRI to exactly its namespace keeps the readable fallback", () => {
  setNamespaces([{ prefix: "ex", name: "http://example.org/" }]);
  assert.equal(compactTerm("http://example.org/"), "example.org");
});

test("termTooltip gives the full IRI, a blank node as _:id and other terms as they are", () => {
  assert.equal(termTooltip("http://schema.org/name"), "http://schema.org/name");
  assert.equal(termTooltip("__rdf_bnode__:b1"), "_:b1");
  assert.equal(termTooltip('__rdf_scoped_bnode__:["scope","b2"]'), "_:b2");
  assert.equal(termTooltip("<_:b3>"), "_:b3");
  assert.equal(termTooltip("<<( urn:a urn:p urn:b )>>"), "<<( urn:a urn:p urn:b )>>");
});

test("node and edge tooltips carry the full IRI", () => {
  const node = { id: "http://example.org/alice", label: "Alice", kind: "iri" };
  assert.equal(nodeTooltip(node, "Person"), "Alice · Person\nhttp://example.org/alice");
  assert.equal(nodeTooltip({ id: "__rdf_bnode__:b1", label: "b1", kind: "blank" }, "Resource"), "b1 · Resource\n_:b1");
  assert.equal(nodeTooltip({ id: "\"42\"", label: "42", kind: "literal" }, "Value"), "42 · Value");
  setNamespaces([{ prefix: "ex", name: "http://example.org/" }]);
  const edge = { predicate: "http://example.org/knows", label: "knows" };
  assert.equal(
    edgeTooltip("Alice", edge, "Bob"),
    "Alice — knows → Bob (ex:knows)\nhttp://example.org/knows",
  );
});

test("namespace rows from the workbench NDJSON page model become prefix/name pairs", () => {
  assert.equal(
    namespacesEndpoint("/rdf4j-workbench/", "my repo"),
    "/rdf4j-workbench/repositories/my%20repo/_internal/namespaces",
  );
  const body = [
    { type: "view", values: { id: "_internal/namespaces" } },
    { type: "vars", values: ["prefix", "namespace"] },
    { type: "rows", values: [[{ value: "rdf4j" }, { value: "http://rdf4j.org/schema/rdf4j#" }], ["", "http://e/"]] },
    { type: "end" },
  ].map((record) => JSON.stringify(record)).join("\n");
  assert.deepEqual(parseNamespaceRows(body), [
    { prefix: "rdf4j", name: "http://rdf4j.org/schema/rdf4j#" },
    { prefix: "", name: "http://e/" },
  ]);
  assert.deepEqual(parseNamespaceRows("not json"), []);
});
